'use strict';
const assert=require('node:assert/strict'),{create}=require('../demo-core'),F=require('../fixtures');let count=0;
const check=(name,fn)=>{fn();count++;console.log('PASS '+name);};
const auth=c=>{c.requestPhone();c.resolvePhone('success');};
const ready=(options={})=>{const c=create(options);c.setRequirement(3.5,12,true);auth(c);c.setDate(F.demoToday);c.select(['SIM_BJ01_U03']);return c;};
const paid=()=>{const c=ready({now:()=>Date.parse('2026-10-26T12:00:00Z')});c.claimCoupons();c.quote();const o=c.submit();c.pay(o.id,'success');return {c,id:o.id};};
check('manual contact permits order entry without unlocking prices',()=>{const c=create();assert.equal(c.hasContact(),false);assert.throws(()=>c.setContact('123'),/ENTER_PHONE/);c.setContact('13800000000');assert(c.hasContact());assert.equal(c.authorized(),false);assert.throws(()=>c.quote(),/PHONE_REQUIRED/);});
check('WeChat contact permits order entry without inventing a raw phone number',()=>{const c=create();auth(c);assert(c.hasContact());const l=c.saveEnterpriseLead({});assert.equal(l.phone,null);assert.equal(l.contact_source,'wechat_authorized');assert.equal(c.state().contactPhone,'');});
check('no implicit capacity term store warehouse or date in fresh state',()=>{const c=create();assert.equal(c.state().requirement.capacity_m3,null);assert.equal(c.state().requirement.term_months,null);assert.equal(c.state().storeId,null);assert.deepEqual(c.state().selected,[]);assert.equal(c.state().startDate,null);});
check('combinations are restricted to two units in one store',()=>{const c=ready();assert.throws(()=>c.select(['SIM_BJ01_U03','SIM_BJ01_U04','SIM_BJ01_U05']),/UNAVAILABLE/);assert.throws(()=>c.select(['SIM_BJ01_U03','SIM_BJ02_U03']),/UNAVAILABLE/);});
check('thirty Beijing stores carry one operating tag and differentiated service tags',()=>{const bj=F.stores.filter(s=>s.city==='北京');assert.equal(bj.length,30);const op=['特价仓','新开门店','双11大促','免费搬运'],sv=['近地铁','24小时存取','电梯直达','停车便利','控温防潮','小推车','全天监控'];assert(bj.every(s=>op.includes(s.operatingTag)&&s.serviceTags.length===3&&s.serviceTags.every(t=>sv.includes(t))));assert.equal(new Set(bj.map(s=>s.serviceTags.join(','))).size,7);assert.equal(bj.find(s=>s.id==='SIM_BJ10').district,'朝阳区');});
check('automatic coupon picks highest eligible rent discount and never discounts deposits',()=>{const c=ready();const base=c.amounts(['SIM_BJ01_U03'],12);c.claimCoupons();const a=c.amounts(['SIM_BJ01_U03'],12);assert.equal(a.coupon_id,'CPN-002');assert.equal(a.coupon_discount,300);assert.equal(a.deposit,base.deposit);assert.equal(a.management_fee,base.management_fee);assert.equal(a.payable,base.payable-300);assert.equal(c.state().coupons.length,3);c.claimCoupons();assert.equal(c.state().coupons.length,3);});
check('coupon choice can disable discount and service benefit cannot reduce rent',()=>{const c=ready();c.claimCoupons();c.setCoupon('none');assert.equal(c.amounts(['SIM_BJ01_U03'],12).coupon_discount,0);c.setCoupon('CPN-003');assert.equal(c.amounts(['SIM_BJ01_U03'],12).coupon_discount,0);c.setCoupon('auto');assert.equal(c.amounts(['SIM_BJ01_U03'],12).coupon_discount,300);});
check('claim apply lock redeem and new-customer invalidation are coherent',()=>{const c=ready();c.claimCoupons();assert.equal(c.state().coupons[1].status,'CLAIMED');c.quote();assert.equal(c.state().coupons[1].status,'APPLIED');const o=c.submit();assert.equal(c.state().coupons[1].status,'LOCKED');c.pay(o.id,'success');assert.equal(c.state().coupons[1].status,'REDEEMED');assert.equal(c.state().coupons[0].status,'INVALID');});
check('failed payment releases both reserved stock and locked coupon',()=>{const c=ready();c.claimCoupons();c.quote();const o=c.submit();c.pay(o.id,'failed');assert.equal(c.state().coupons[1].status,'CLAIMED');assert(c.selectionValid(o.unit_ids));});
check('expired pending order cannot pay and releases stock/coupon',()=>{let time=0;const c=ready({now:()=>time});c.claimCoupons();c.quote();const o=c.submit();time=15*60*1000+1;assert.throws(()=>c.pay(o.id,'success'),/ORDER_EXPIRED/);assert.equal(c.orderDetail(o.id).status,'expired');assert(c.selectionValid(o.unit_ids));assert.equal(c.state().coupons[1].status,'CLAIMED');});
check('pending payment rechecks stock and does not overwrite a changed stock state',()=>{const c=ready();c.claimCoupons();c.quote();const o=c.submit();c.markUnavailable(o.unit_ids[0]);assert.throws(()=>c.pay(o.id,'success'),/QUOTE_STALE/);assert.equal(c.state().stock[o.unit_ids[0]],'soldout');assert.equal(c.orderDetail(o.id).status,'invalidated');});
check('cancellation is only available for pending orders',()=>{const c=ready();c.quote();const o=c.submit();c.cancelOrder(o.id);assert(c.selectionValid(o.unit_ids));assert.throws(()=>c.cancelOrder(o.id),/INVALID_ORDER_STATE/);});
check('identity and date checks are independent of phone authorization',()=>{const {c,id}=paid();assert.throws(()=>c.enterStorage(id),/IDENTITY_REQUIRED/);c.identity(id,'failed');assert.throws(()=>c.enterStorage(id),/IDENTITY_REQUIRED/);c.identity(id,'success');c.enterStorage(id);assert.equal(c.orderDetail(id).service.useStatus,'active');const future=ready({now:()=>Date.parse('2026-10-26')});future.setDate('2026-11-01');future.quote();const o=future.submit();future.pay(o.id,'success');future.identity(o.id,'success');assert.throws(()=>future.enterStorage(o.id),/BEFORE_START/);});
check('renewal is re-priced and renewal coupon only applies to six or more months',()=>{const {c,id}=paid();assert.throws(()=>c.renewalQuote(id,0),/SELECT_TERM/);assert.equal(c.renewalQuote(id,3).coupon_discount,0);const q=c.renewalQuote(id,6);assert.equal(q.coupon_discount,150);assert.equal(q.deposit,0);assert.equal(q.management_fee,0);c.payRenewal(id);assert.equal(c.orderDetail(id).service.renewals.length,1);assert.throws(()=>c.payRenewal(id),/QUOTE_STALE/);});
check('exit inspection failure retry pass and refund require the right prior state',()=>{const {c,id}=paid();assert.throws(()=>c.requestExit(id,F.demoToday,true),/ACTIVE_ORDER_REQUIRED/);c.identity(id,'success');c.enterStorage(id);assert.throws(()=>c.requestExit(id,F.demoToday,false),/EMPTY_REQUIRED/);c.requestExit(id,F.demoToday,true);assert.throws(()=>c.refundDeposit(id),/INSPECTION_REQUIRED/);assert.throws(()=>c.renewalQuote(id,6),/EXIT_IN_PROGRESS/);c.inspectExit(id,'failed');c.retryExit(id);c.inspectExit(id,'passed');assert.equal(c.orderDetail(id).service.deposit,'processing');c.refundDeposit(id);assert.equal(c.orderDetail(id).service.deposit,'refunded_simulated');assert.equal(c.state().stock[c.orderDetail(id).unit_ids[0]],'available');assert.throws(()=>c.enterStorage(id),/ORDER_CLOSED/);});
check('invoice is linked to a paid record and never duplicated',()=>{const {c,id}=paid();assert.throws(()=>c.requestInvoice(id,{title:'公司',email:'bad'}),/INVOICE_FIELDS/);const iv=c.requestInvoice(id,{title:'公司',email:'qa@example.com',payment:id});assert.equal(iv.amount,c.orderDetail(id).rent_after_coupon+c.orderDetail(id).management_fee);assert.throws(()=>c.requestInvoice(id,{title:'公司',email:'qa@example.com'}),/INVOICE_EXISTS/);assert.equal(iv.status,'requested_locally');});
check('transport remains advisor-confirmed and cannot silently grant free transport',()=>{const {c,id}=paid();assert.throws(()=>c.requestTransport(id,{address:'',date:F.demoToday}),/TRANSPORT_FIELDS/);const t=c.requestTransport(id,{address:'北京市西城区用仓地址',date:F.demoToday});assert.equal(t.eligibility,'pending_confirmation');assert.equal(t.status,'awaiting_advisor');assert.equal(t.free,undefined);});
check('personal lead inherits confirmed intention/contact but never binds store/unit',()=>{const c=create();c.setRequirement(5,6,true);c.setContact('13800000000');c.setStore('SIM_BJ03');const l=c.saveLead('北京市用仓地址');assert.equal(l.capacity_m3,5);assert.equal(l.term_months,6);assert.equal(l.phone,'13800000000');assert.equal(l.store_id,undefined);assert.equal(l.unit_ids,undefined);c.editLead(l.id,{address:'北京市新地址',note:'修改备注'});assert.equal(c.state().leads[0].capacity_m3,5);c.withdrawLead(l.id);assert.equal(c.state().leads[0].status,'withdrawn');assert.throws(()=>c.editLead(l.id,{address:'另一个地址'}),/LEAD_WITHDRAWN/);});
check('consultation has local status and preserves order context',()=>{const {c,id}=paid();const m=c.saveSupport({text:'请核对入仓安排',order_id:id,type:'order'});assert.equal(m.order_id,id);assert.equal(m.status,'saved_locally');assert.throws(()=>c.saveSupport({text:'',order_id:id}),/ENTER_QUESTION/);assert.throws(()=>c.saveSupport({text:'咨询',order_id:'missing'}),/ORDER_NOT_FOUND/);});
check('new state round trip retains coupon order service and privacy boundaries',()=>{const {c,id}=paid();c.identity(id,'success');const d=create({state:c.state(),now:()=>Date.parse('2026-10-26T12:00:00Z')});assert.equal(d.orderDetail(id).service.identity,'verified');assert.equal(d.state().coupons.find(x=>x.id==='CPN-002').status,'REDEEMED');d.revokePhone();assert.equal(d.authorized(),false);assert(d.state().orders.length===1);});
check('returning to the UI expires pending orders and releases locks without a payment click',()=>{let time=0;const c=ready({now:()=>time});c.claimCoupons();c.quote();const o=c.submit();assert.equal(c.expirePendingOrders(),0);time=15*60*1000;assert.equal(c.expirePendingOrders(),1);assert.equal(c.orderDetail(o.id).status,'expired');assert(c.selectionValid(o.unit_ids));assert.equal(c.expirePendingOrders(),0);assert.equal(c.state().coupons.find(x=>x.id===o.coupon_id).status,'CLAIMED');});
check('E-store advice inherits intention but remains distinct from enterprise/order binding',()=>{const c=create();c.setRequirement(4,6,true);const l=c.saveLead('北京市取送地址',{service_source:'estore'});assert.equal(l.service_source,'estore');assert.equal(l.capacity_m3,4);assert.equal(l.term_months,6);assert.equal(l.store_id,undefined);assert.equal(c.state().enterpriseLeads.length,0);assert.equal(c.state().orders.length,0);});
console.log(JSON.stringify({groups:count,result:'PASS',fixture:F.version}));
